1	//===-- Base class for libc unittests ---------------------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	
9	#ifndef LLVM_LIBC_TEST_UNITTEST_LIBCTEST_H
10	#define LLVM_LIBC_TEST_UNITTEST_LIBCTEST_H
11	
12	// This is defined as a simple macro in test.h so that it exists for platforms
13	// that don't use our test infrastructure. It's defined as a proper function
14	// below.
15	#include "src/__support/macros/config.h"
16	#ifdef libc_make_test_file_path
17	#undef libc_make_test_file_path
18	#endif // libc_make_test_file_path
19	
20	// This is defined as a macro here to avoid namespace issues.
21	#define libc_make_test_file_path(file_name)                                    \
22	  (LIBC_NAMESPACE::testing::libc_make_test_file_path_func(file_name))
23	
24	// This file can only include headers from src/__support/ or test/UnitTest. No
25	// other headers should be included.
26	
27	#include "src/__support/CPP/string.h"
28	#include "src/__support/CPP/string_view.h"
29	#include "src/__support/CPP/type_traits.h"
30	#include "src/__support/c_string.h"
31	#include "src/__support/macros/properties/compiler.h"
32	#include "test/UnitTest/ExecuteFunction.h"
33	#include "test/UnitTest/TestLogger.h"
34	
35	namespace LIBC_NAMESPACE_DECL {
36	namespace testing {
37	
38	// Only the following conditions are supported. Notice that we do not have
39	// a TRUE or FALSE condition. That is because, C library functions do not
40	// return boolean values, but use integral return values to indicate true or
41	// false conditions. Hence, it is more appropriate to use the other comparison
42	// conditions for such cases.
43	enum class TestCond { EQ, NE, LT, LE, GT, GE };
44	
45	struct MatcherBase {
46	  virtual ~MatcherBase() {}
47	  virtual void explainError() { tlog << "unknown error\n"; }
48	  // Override and return true to skip `explainError` step.
49	  virtual bool is_silent() const { return false; }
50	};
51	
52	template <typename T> struct Matcher : public MatcherBase {
53	  bool match(const T &t);
54	};
55	
56	namespace internal {
57	
58	// A simple location object to allow consistent passing of __FILE__ and
59	// __LINE__.
60	struct Location {
61	  Location(const char *file, int line) : file(file), line(line) {}
62	  const char *file;
63	  int line;
64	};
65	
66	// Supports writing a failing Location to tlog.
67	TestLogger &operator<<(TestLogger &logger, Location Loc);
68	
69	#define LIBC_TEST_LOC_()                                                       \
70	  LIBC_NAMESPACE::testing::internal::Location(__FILE__, __LINE__)
71	
72	// Object to forward custom logging after the EXPECT / ASSERT macros.
73	struct Message {
74	  template <typename T> Message &operator<<(T value) {
75	    tlog << value;
76	    return *this;
77	  }
78	};
79	
80	// A trivial object to catch the Message, this enables custom logging and
81	// returning from the test function, see LIBC_TEST_SCAFFOLDING_ below.
82	struct Failure {
83	  void operator=([[maybe_unused]] Message msg) {}
84	};
85	
86	struct RunContext {
87	  enum class RunResult : bool { Pass, Fail };
88	
89	  RunResult status() const { return Status; }
90	
91	  void markFail() { Status = RunResult::Fail; }
92	
93	private:
94	  RunResult Status = RunResult::Pass;
95	};
96	
97	template <typename ValType>
98	bool test_impl(RunContext *Ctx, TestCond Cond, ValType LHS, ValType RHS,
99	               const char *LHSStr, const char *RHSStr, Location Loc);
100	
101	extern RunContext *current_context;
102	
103	// We make use of a template function, with |LHS| and |RHS| as explicit
104	// parameters, for enhanced type checking. Other gtest like unittest
105	// frameworks have a similar function which takes a boolean argument
106	// instead of the explicit |LHS| and |RHS| arguments. This boolean argument
107	// is the result of the |Cond| operation on |LHS| and |RHS|. Though not bad,
108	// |Cond| on mismatched |LHS| and |RHS| types can potentially succeed because
109	// of type promotion.
110	template <typename ValType, cpp::enable_if_t<cpp::is_integral_v<ValType> ||
111	                                                 is_big_int_v<ValType> ||
112	                                                 cpp::is_fixed_point_v<ValType>,
113	                                             int> = 0>
114	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
115	          const char *RHSStr, internal::Location Loc) {
116	  return test_impl(current_context, Cond, LHS, RHS, LHSStr, RHSStr, Loc);
117	}
118	
119	template <typename ValType, cpp::enable_if_t<cpp::is_enum_v<ValType>, int> = 0>
120	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
121	          const char *RHSStr, internal::Location Loc) {
122	  return test_impl(current_context, Cond, (long long)LHS, (long long)RHS,
123	                   LHSStr, RHSStr, Loc);
124	}
125	
126	template <typename ValType,
127	          cpp::enable_if_t<cpp::is_pointer_v<ValType>, ValType> = nullptr>
128	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
129	          const char *RHSStr, internal::Location Loc) {
130	  return test_impl(current_context, Cond, (unsigned long long)LHS,
131	                   (unsigned long long)RHS, LHSStr, RHSStr, Loc);
132	}
133	
134	// Helper to allow macro invocations like `ASSERT_EQ(foo, nullptr)`.
135	template <typename ValType,
136	          cpp::enable_if_t<cpp::is_pointer_v<ValType>, ValType> = nullptr>
137	bool test(TestCond Cond, ValType LHS, cpp::nullptr_t, const char *LHSStr,
138	          const char *RHSStr, internal::Location Loc) {
139	  return test(Cond, LHS, static_cast<ValType>(nullptr), LHSStr, RHSStr, Loc);
140	}
141	
142	template <
143	    typename ValType,
144	    cpp::enable_if_t<cpp::is_same_v<ValType, LIBC_NAMESPACE::cpp::string_view>,
145	                     int> = 0>
146	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
147	          const char *RHSStr, internal::Location Loc) {
148	  return test_impl(current_context, Cond, LHS, RHS, LHSStr, RHSStr, Loc);
149	}
150	
151	template <
152	    typename ValType,
153	    cpp::enable_if_t<cpp::is_same_v<ValType, LIBC_NAMESPACE::cpp::wstring_view>,
154	                     int> = 0>
155	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
156	          const char *RHSStr, internal::Location Loc) {
157	  return test_impl(current_context, Cond, LHS, RHS, LHSStr, RHSStr, Loc);
158	}
159	
160	template <typename ValType,
161	          cpp::enable_if_t<cpp::is_same_v<ValType, LIBC_NAMESPACE::cpp::string>,
162	                           int> = 0>
163	bool test(TestCond Cond, ValType LHS, ValType RHS, const char *LHSStr,
164	          const char *RHSStr, internal::Location Loc) {
165	  return test_impl(current_context, Cond, LHS, RHS, LHSStr, RHSStr, Loc);
166	}
167	
168	bool test_str_eq(const char *LHS, const char *RHS, const char *LHSStr,
169	                 const char *RHSStr, internal::Location Loc);
170	
171	bool test_str_ne(const char *LHS, const char *RHS, const char *LHSStr,
172	                 const char *RHSStr, internal::Location Loc);
173	
174	} // namespace internal
175	
176	struct TestOptions {
177	  // If set, then just this one test from the suite will be run.
178	  const char *TestFilter = nullptr;
179	  // Should the test results print color codes to stdout?
180	  bool PrintColor = true;
181	  // Should the test results print timing only in milliseconds, as GTest does?
182	  bool TimeInMs = false;
183	};
184	
185	// NOTE: One should not create instances and call methods on them directly. One
186	// should use the macros TEST or TEST_F to write test cases.
187	class Test {
188	  Test *Next = nullptr;
189	
190	  static int getNumTests();
191	
192	public:
193	  virtual ~Test() {}
194	  virtual void SetUp() {}
195	  virtual void TearDown() {}
196	
197	  static int runTests(const TestOptions &Options);
198	
199	protected:
200	  static void addTest(Test *T);
201	
202	  bool testMatch(bool MatchResult, MatcherBase &Matcher, const char *LHSStr,
203	                 const char *RHSStr, internal::Location Loc);
204	
205	  template <typename MatcherT, typename ValType>
206	  bool matchAndExplain(MatcherT &&Matcher, ValType Value,
207	                       const char *MatcherStr, const char *ValueStr,
208	                       internal::Location Loc) {
209	    return testMatch(Matcher.match(Value), Matcher, ValueStr, MatcherStr, Loc);
210	  }
211	
212	  bool testProcessExits(testutils::FunctionCaller *Func, int ExitCode,
213	                        const char *LHSStr, const char *RHSStr,
214	                        internal::Location Loc);
215	
216	  bool testProcessKilled(testutils::FunctionCaller *Func, int Signal,
217	                         const char *LHSStr, const char *RHSStr,
218	                         internal::Location Loc);
219	
220	  template <typename Func> testutils::FunctionCaller *createCallable(Func f) {
221	    struct Callable : public testutils::FunctionCaller {
222	      Func f;
223	      Callable(Func f) : f(f) {}
224	      void operator()() override { f(); }
225	    };
226	
227	    return new Callable(f);
228	  }
229	
230	private:
231	  virtual void Run() = 0;
232	  virtual const char *getName() const = 0;
233	
234	  static Test *Start;
235	  static Test *End;
236	};
237	
238	extern int argc;
239	extern char **argv;
240	extern char **envp;
241	
242	namespace internal {
243	
244	constexpr bool same_prefix(char const *lhs, char const *rhs, int const len) {
245	  for (int i = 0; (*lhs || *rhs) && (i < len); ++lhs, ++rhs, ++i)
246	    if (*lhs != *rhs)
247	      return false;
248	  return true;
249	}
250	
251	constexpr bool valid_prefix(char const *lhs) {
252	  return same_prefix(lhs, "LlvmLibc", 8);
253	}
254	
255	// 'str' is a null terminated string of the form
256	// "const char *LIBC_NAMESPACE::testing::internal::GetTypeName() [ParamType =
257	// XXX]" We return the substring that start at character '[' or a default
258	// message.
259	constexpr char const *GetPrettyFunctionParamType(char const *str) {
260	  for (const char *ptr = str; *ptr != '\0'; ++ptr)
261	    if (*ptr == '[')
262	      return ptr;
263	  return "UNSET : declare with REGISTER_TYPE_NAME";
264	}
265	
266	// This function recovers ParamType at compile time by using __PRETTY_FUNCTION__
267	// It can be customized by using the REGISTER_TYPE_NAME macro below.
268	template <typename ParamType> static constexpr const char *GetTypeName() {
269	#ifdef LIBC_COMPILER_IS_MSVC
270	  return GetPrettyFunctionParamType(__FUNCSIG__);
271	#else
272	  return GetPrettyFunctionParamType(__PRETTY_FUNCTION__);
273	#endif // LIBC_COMPILER_IS_MSVC
274	}
275	
276	template <typename T>
277	static inline void GenerateName(char *buffer, int buffer_size,
278	                                const char *prefix) {
279	  if (buffer_size == 0)
280	    return;
281	
282	  // Make sure string is null terminated.
283	  --buffer_size;
284	  buffer[buffer_size] = '\0';
285	
286	  const auto AppendChar = [&](char c) {
287	    if (buffer_size > 0) {
288	      *buffer = c;
289	      ++buffer;
290	      --buffer_size;
291	    }
292	  };
293	  const auto AppendStr = [&](const char *str) {
294	    for (; str && *str != '\0'; ++str)
295	      AppendChar(*str);
296	  };
297	
298	  AppendStr(prefix);
299	  AppendChar(' ');
300	  AppendStr(GetTypeName<T>());
301	  AppendChar('\0');
302	}
303	
304	// TestCreator implements a linear hierarchy of test instances, effectively
305	// instanciating all tests with Types in a single object.
306	template <template <typename> class TemplatedTestClass, typename... Types>
307	struct TestCreator;
308	
309	template <template <typename> class TemplatedTestClass, typename Head,
310	          typename... Tail>
311	struct TestCreator<TemplatedTestClass, Head, Tail...>
312	    : private TestCreator<TemplatedTestClass, Tail...> {
313	  TemplatedTestClass<Head> instance;
314	};
315	
316	template <template <typename> class TemplatedTestClass>
317	struct TestCreator<TemplatedTestClass> {};
318	
319	// A type list to declare the set of types to instantiate the tests with.
320	template <typename... Types> struct TypeList {
321	  template <template <typename> class TemplatedTestClass> struct Tests {
322	    using type = TestCreator<TemplatedTestClass, Types...>;
323	  };
324	};
325	
326	} // namespace internal
327	
328	// Make TypeList visible in LIBC_NAMESPACE::testing.
329	template <typename... Types> using TypeList = internal::TypeList<Types...>;
330	
331	CString libc_make_test_file_path_func(const char *file_name);
332	
333	} // namespace testing
334	} // namespace LIBC_NAMESPACE_DECL
335	
336	// For TYPED_TEST and TYPED_TEST_F below we need to display which type was used
337	// to run the test. The default will return the fully qualified canonical type
338	// but it can be difficult to read. We provide the following macro to allow the
339	// client to register the type name as they see it in the code.
340	#define REGISTER_TYPE_NAME(TYPE)                                               \
341	  template <>                                                                  \
342	  constexpr const char *                                                       \
343	  LIBC_NAMESPACE::testing::internal::GetTypeName<TYPE>() {                     \
344	    return "[ParamType = " #TYPE "]";                                          \
345	  }
346	
347	#define TYPED_TEST(SuiteName, TestName, TypeList)                              \
348	  static_assert(                                                               \
349	      LIBC_NAMESPACE::testing::internal::valid_prefix(#SuiteName),             \
350	      "All LLVM-libc TYPED_TEST suite names must start with 'LlvmLibc'.");     \
351	  template <typename T>                                                        \
352	  class SuiteName##_##TestName : public LIBC_NAMESPACE::testing::Test {        \
353	  public:                                                                      \
354	    using ParamType = T;                                                       \
355	    char name[256];                                                            \
356	    SuiteName##_##TestName() {                                                 \
357	      addTest(this);                                                           \
358	      LIBC_NAMESPACE::testing::internal::GenerateName<T>(                      \
359	          name, sizeof(name), #SuiteName "." #TestName);                       \
360	    }                                                                          \
361	    void Run() override;                                                       \
362	    const char *getName() const override { return name; }                      \
363	  };                                                                           \
364	  TypeList::Tests<SuiteName##_##TestName>::type                                \
365	      SuiteName##_##TestName##_Instance;                                       \
366	  template <typename T> void SuiteName##_##TestName<T>::Run()
367	
368	#define TYPED_TEST_F(SuiteClass, TestName, TypeList)                           \
369	  static_assert(LIBC_NAMESPACE::testing::internal::valid_prefix(#SuiteClass),  \
370	                "All LLVM-libc TYPED_TEST_F suite class names must start "     \
371	                "with 'LlvmLibc'.");                                           \
372	  template <typename T> class SuiteClass##_##TestName : public SuiteClass<T> { \
373	  public:                                                                      \
374	    using ParamType = T;                                                       \
375	    char name[256];                                                            \
376	    SuiteClass##_##TestName() {                                                \
377	      SuiteClass<T>::addTest(this);                                            \
378	      LIBC_NAMESPACE::testing::internal::GenerateName<T>(                      \
379	          name, sizeof(name), #SuiteClass "." #TestName);                      \
380	    }                                                                          \
381	    void Run() override;                                                       \
382	    const char *getName() const override { return name; }                      \
383	  };                                                                           \
384	  TypeList::Tests<SuiteClass##_##TestName>::type                               \
385	      SuiteClass##_##TestName##_Instance;                                      \
386	  template <typename T> void SuiteClass##_##TestName<T>::Run()
387	
388	#define TEST(SuiteName, TestName)                                              \
389	  static_assert(LIBC_NAMESPACE::testing::internal::valid_prefix(#SuiteName),   \
390	                "All LLVM-libc TEST suite names must start with 'LlvmLibc'."); \
391	  class SuiteName##_##TestName : public LIBC_NAMESPACE::testing::Test {        \
392	  public:                                                                      \
393	    SuiteName##_##TestName() { addTest(this); }                                \
394	    void Run() override;                                                       \
395	    const char *getName() const override { return #SuiteName "." #TestName; }  \
396	  };                                                                           \
397	  SuiteName##_##TestName SuiteName##_##TestName##_Instance;                    \
398	  void SuiteName##_##TestName::Run()
399	
400	#define TEST_F(SuiteClass, TestName)                                           \
401	  static_assert(                                                               \
402	      LIBC_NAMESPACE::testing::internal::valid_prefix(#SuiteClass),            \
403	      "All LLVM-libc TEST_F suite class names must start with 'LlvmLibc'.");   \
404	  class SuiteClass##_##TestName : public SuiteClass {                          \
405	  public:                                                                      \
406	    SuiteClass##_##TestName() { addTest(this); }                               \
407	    void Run() override;                                                       \
408	    const char *getName() const override { return #SuiteClass "." #TestName; } \
409	  };                                                                           \
410	  SuiteClass##_##TestName SuiteClass##_##TestName##_Instance;                  \
411	  void SuiteClass##_##TestName::Run()
412	
413	// Helper to trick the compiler into ignoring lack of braces on the else
414	// branch.  We cannot introduce braces at this point, since it would prevent
415	// using `<< ...` after the test macro for additional failure output.
416	#define LIBC_TEST_DISABLE_DANGLING_ELSE                                        \
417	  switch (0)                                                                   \
418	  case 0:                                                                      \
419	  default: // NOLINT
420	
421	// If RET_OR_EMPTY is the 'return' keyword we perform an early return which
422	// corresponds to an assert. If it is empty the execution continues, this
423	// corresponds to an expect.
424	//
425	// The 'else' clause must not be enclosed into braces so that the << operator
426	// can be used to fill the Message.
427	//
428	// TEST is usually implemented as a function performing checking logic and
429	// returning a boolean. This expression is responsible for logging the
430	// diagnostic in case of failure.
431	#define LIBC_TEST_SCAFFOLDING_(TEST, RET_OR_EMPTY)                             \
432	  LIBC_TEST_DISABLE_DANGLING_ELSE                                              \
433	  if (TEST)                                                                    \
434	    ;                                                                          \
435	  else                                                                         \
436	    RET_OR_EMPTY LIBC_NAMESPACE::testing::internal::Failure() =                \
437	        LIBC_NAMESPACE::testing::internal::Message()
438	
439	#define LIBC_TEST_BINOP_(COND, LHS, RHS, RET_OR_EMPTY)                         \
440	  LIBC_TEST_SCAFFOLDING_(LIBC_NAMESPACE::testing::internal::test(              \
441	                             LIBC_NAMESPACE::testing::TestCond::COND, LHS,     \
442	                             RHS, #LHS, #RHS, LIBC_TEST_LOC_()),               \
443	                         RET_OR_EMPTY)
444	
445	////////////////////////////////////////////////////////////////////////////////
446	// Binary operations corresponding to the TestCond enum.
447	
448	#define EXPECT_EQ(LHS, RHS) LIBC_TEST_BINOP_(EQ, LHS, RHS, )
449	#define ASSERT_EQ(LHS, RHS) LIBC_TEST_BINOP_(EQ, LHS, RHS, return)
450	
451	#define EXPECT_NE(LHS, RHS) LIBC_TEST_BINOP_(NE, LHS, RHS, )
452	#define ASSERT_NE(LHS, RHS) LIBC_TEST_BINOP_(NE, LHS, RHS, return)
453	
454	#define EXPECT_LT(LHS, RHS) LIBC_TEST_BINOP_(LT, LHS, RHS, )
455	#define ASSERT_LT(LHS, RHS) LIBC_TEST_BINOP_(LT, LHS, RHS, return)
456	
457	#define EXPECT_LE(LHS, RHS) LIBC_TEST_BINOP_(LE, LHS, RHS, )
458	#define ASSERT_LE(LHS, RHS) LIBC_TEST_BINOP_(LE, LHS, RHS, return)
459	
460	#define EXPECT_GT(LHS, RHS) LIBC_TEST_BINOP_(GT, LHS, RHS, )
461	#define ASSERT_GT(LHS, RHS) LIBC_TEST_BINOP_(GT, LHS, RHS, return)
462	
463	#define EXPECT_GE(LHS, RHS) LIBC_TEST_BINOP_(GE, LHS, RHS, )
464	#define ASSERT_GE(LHS, RHS) LIBC_TEST_BINOP_(GE, LHS, RHS, return)
465	
466	////////////////////////////////////////////////////////////////////////////////
467	// Boolean checks are handled as comparison to the true / false values.
468	
469	#define EXPECT_TRUE(VAL) EXPECT_EQ(VAL, true)
470	#define ASSERT_TRUE(VAL) ASSERT_EQ(VAL, true)
471	
472	#define EXPECT_FALSE(VAL) EXPECT_EQ(VAL, false)
473	#define ASSERT_FALSE(VAL) ASSERT_EQ(VAL, false)
474	
475	////////////////////////////////////////////////////////////////////////////////
476	// String checks.
477	
478	#define LIBC_TEST_STR_(TEST_FUNC, LHS, RHS, RET_OR_EMPTY)                      \
479	  LIBC_TEST_SCAFFOLDING_(TEST_FUNC(LHS, RHS, #LHS, #RHS, LIBC_TEST_LOC_()),    \
480	                         RET_OR_EMPTY)
481	
482	#define EXPECT_STREQ(LHS, RHS)                                                 \
483	  LIBC_TEST_STR_(LIBC_NAMESPACE::testing::internal::test_str_eq, LHS, RHS, )
484	#define ASSERT_STREQ(LHS, RHS)                                                 \
485	  LIBC_TEST_STR_(LIBC_NAMESPACE::testing::internal::test_str_eq, LHS, RHS,     \
486	                 return)
487	
488	#define EXPECT_STRNE(LHS, RHS)                                                 \
489	  LIBC_TEST_STR_(LIBC_NAMESPACE::testing::internal::test_str_ne, LHS, RHS, )
490	#define ASSERT_STRNE(LHS, RHS)                                                 \
491	  LIBC_TEST_STR_(LIBC_NAMESPACE::testing::internal::test_str_ne, LHS, RHS,     \
492	                 return)
493	
494	////////////////////////////////////////////////////////////////////////////////
495	// Subprocess checks.
496	
497	#if LIBC_TEST_SUBPROCESS_TESTS
498	
499	#define LIBC_TEST_PROCESS_(TEST_FUNC, FUNC, VALUE, RET_OR_EMPTY)               \
500	  LIBC_TEST_SCAFFOLDING_(                                                      \
501	      TEST_FUNC(LIBC_NAMESPACE::testing::Test::createCallable(FUNC), VALUE,    \
502	                #FUNC, #VALUE, LIBC_TEST_LOC_()),                              \
503	      RET_OR_EMPTY)
504	
505	#define EXPECT_EXITS(FUNC, EXIT)                                               \
506	  LIBC_TEST_PROCESS_(testProcessExits, FUNC, EXIT, )
507	#define ASSERT_EXITS(FUNC, EXIT)                                               \
508	  LIBC_TEST_PROCESS_(testProcessExits, FUNC, EXIT, return)
509	
510	#ifdef LIBC_TEST_SKIP_DEATH_TESTS
511	
512	#define EXPECT_DEATH(FUNC, SIG)
513	#define ASSERT_DEATH(FUNC, SIG)
514	
515	#else
516	
517	#define EXPECT_DEATH(FUNC, SIG)                                                \
518	  LIBC_TEST_PROCESS_(testProcessKilled, FUNC, SIG, )
519	#define ASSERT_DEATH(FUNC, SIG)                                                \
520	  LIBC_TEST_PROCESS_(testProcessKilled, FUNC, SIG, return)
521	
522	#endif // LIBC_TEST_SKIP_DEATH_TESTS
523	
524	#endif // LIBC_TEST_SUBPROCESS_TESTS
525	
526	////////////////////////////////////////////////////////////////////////////////
527	// Custom matcher checks.
528	
529	#define LIBC_TEST_MATCH_(MATCHER, MATCH, MATCHER_STR, MATCH_STR, RET_OR_EMPTY) \
530	  LIBC_TEST_SCAFFOLDING_(matchAndExplain(MATCHER, MATCH, MATCHER_STR,          \
531	                                         MATCH_STR, LIBC_TEST_LOC_()),         \
532	                         RET_OR_EMPTY)
533	
534	#define EXPECT_THAT(MATCH, MATCHER)                                            \
535	  LIBC_TEST_MATCH_(MATCHER, MATCH, #MATCHER, #MATCH, )
536	#define ASSERT_THAT(MATCH, MATCHER)                                            \
537	  LIBC_TEST_MATCH_(MATCHER, MATCH, #MATCHER, #MATCH, return)
538	
539	#define WITH_SIGNAL(X) X
540	
541	#define LIBC_TEST_HAS_MATCHERS() (1)
542	
543	#endif // LLVM_LIBC_TEST_UNITTEST_LIBCTEST_H
544

