2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	/// \file
9	/// ErrnoSetterMatcher is a testing utility to assert system call/function
10	/// return values and the expected libc_errno.
11	///
12	/// Usage:
13	///
14	///   1. Asserting success (return value matches and libc_errno is 0):
15	///
16	///      EXPECT_THAT(LIBC_NAMESPACE::close(fd), Succeeds(0));
17	///
18	///   2. Asserting failure (return value is -1 and libc_errno matches expected):
19	///
20	///      EXPECT_THAT(LIBC_NAMESPACE::read(-1, buf, 1), Fails(EBADF));
21	///
22	///   3. Asserting failure with custom return value:
23	///
24	///      EXPECT_THAT(LIBC_NAMESPACE::mmap(nullptr, size, ...),
25	///                  Fails(ENOMEM, MAP_FAILED));
26	///
27	///   4. Asserting failure with multiple possible errnos (e.g. QEMU vs actual
28	///      hardware):
29	///
30	///      EXPECT_THAT(LIBC_NAMESPACE::socketpair(-1, -1, -1, sv),
31	///                  Fails(any_of(EINVAL, EAFNOSUPPORT)));
32	//===----------------------------------------------------------------------===//
33	
34	#ifndef LLVM_LIBC_TEST_ERRNOSETTERMATCHER_H
35	#define LLVM_LIBC_TEST_ERRNOSETTERMATCHER_H
36	
37	#include "src/__support/FPUtil/FPBits.h"
38	#include "src/__support/FPUtil/fpbits_str.h"
39	#include "src/__support/StringUtil/error_to_string.h"
40	#include "src/__support/libc_errno.h"
41	#include "src/__support/macros/config.h"
42	#include "src/__support/macros/properties/architectures.h"
43	#include "test/UnitTest/Test.h"
44	
45	namespace LIBC_NAMESPACE_DECL {
46	namespace testing {
47	
48	struct ErrnoList {
49	  int errs[4];
50	  size_t count;
51	};
52	
53	namespace internal {
54	
55	enum class CompareAction { EQ = 0, GE, GT, LE, LT, NE };
56	
57	constexpr const char *CompareMessage[] = {
58	    "equal to",     "greater than or equal to",
59	    "greater than", "less than or equal to",
60	    "less than",    "not equal to"};
61	
62	template <typename T> struct Comparator {
63	  CompareAction cmp;
64	  T expected;
65	  bool compare(T actual) {
66	    switch (cmp) {
67	    case CompareAction::EQ:
68	      return actual == expected;
69	    case CompareAction::NE:
70	      return actual != expected;
71	    case CompareAction::GE:
72	      return actual >= expected;
73	    case CompareAction::GT:
74	      return actual > expected;
75	    case CompareAction::LE:
76	      return actual <= expected;
77	    case CompareAction::LT:
78	      return actual < expected;
79	    }
80	    __builtin_unreachable();
81	  }
82	
83	  // The NVPTX backend cannot handle circular dependencies on global variables.
84	  // We provide a constant dummy implementation to prevent this from occurring.
85	#ifdef LIBC_TARGET_ARCH_IS_NVPTX
86	  constexpr const char *str() { return ""; }
87	#else
88	  const char *str() { return CompareMessage[static_cast<int>(cmp)]; }
89	#endif
90	};
91	
92	class ErrnoCheck {
93	  enum class Type { EQ = 0, NE, ANY_OF } type;
94	  int expected;
95	  int expected_list[4];
96	  size_t list_count;
97	
98	public:
99	  ErrnoCheck() : type(Type::EQ), expected(0), list_count(0) {}
100	  ErrnoCheck(int val) : type(Type::EQ), expected(val), list_count(0) {}
101	  template <typename T> ErrnoCheck(Comparator<T> cmp) : list_count(0) {
102	    if (cmp.cmp == CompareAction::NE) {
103	      type = Type::NE;
104	    } else {
105	      type = Type::EQ;
106	    }
107	    expected = static_cast<int>(cmp.expected);
108	  }
109	  ErrnoCheck(const ErrnoList &list)
110	      : type(Type::ANY_OF), expected(0), list_count(list.count) {
111	    for (size_t i = 0; i < list.count && i < 4; ++i) {
112	      expected_list[i] = list.errs[i];
113	    }
114	  }
115	
116	  bool compare(int actual) const {
117	    if (type == Type::EQ) {
118	      return actual == expected;
119	    } else if (type == Type::NE) {
120	      return actual != expected;
121	    } else if (type == Type::ANY_OF) {
122	      for (size_t i = 0; i < list_count; ++i) {
123	        if (actual == expected_list[i])
124	          return true;
125	      }
126	      return false;
127	    }
128	    return false;
129	  }
130	
131	  void print_expected() const {
132	    if (type == Type::EQ) {
133	      auto expected_str = try_get_errno_name(expected);
134	      tlog << "equal to " << (expected_str ? *expected_str : "<unknown>") << "("
135	           << expected << ")";
136	    } else if (type == Type::NE) {
137	      auto expected_str = try_get_errno_name(expected);
138	      tlog << "not equal to " << (expected_str ? *expected_str : "<unknown>")
139	           << "(" << expected << ")";
140	    } else if (type == Type::ANY_OF) {
141	      tlog << "one of [";
142	      for (size_t i = 0; i < list_count; ++i) {
143	        auto expected_str = try_get_errno_name(expected_list[i]);
144	        tlog << (expected_str ? *expected_str : "<unknown>") << "("
145	             << expected_list[i] << ")";
146	        if (i + 1 < list_count)
147	          tlog << ", ";
148	      }
149	      tlog << "]";
150	    }
151	  }
152	};
153	
154	template <typename T> class ErrnoSetterMatcher : public Matcher<T> {
155	  Comparator<T> return_cmp;
156	  ErrnoCheck errno_cmp;
157	  T actual_return;
158	  int actual_errno;
159	
160	  // Even though this is a errno matcher primarily, it has to cater to platforms
161	  // which do not have an errno. This predicate checks if errno matching is to
162	  // be skipped.
163	  static constexpr bool ignore_errno() {
164	#ifdef LIBC_TARGET_ARCH_IS_GPU
165	    return true;
166	#else
167	    return false;
168	#endif
169	  }
170	
171	public:
172	  ErrnoSetterMatcher(Comparator<T> rcmp) : return_cmp(rcmp) {}
173	  ErrnoSetterMatcher(Comparator<T> rcmp, ErrnoCheck ecmp)
174	      : return_cmp(rcmp), errno_cmp(ecmp) {}
175	
176	  ErrnoSetterMatcher<T> with_errno(ErrnoCheck ecmp) {
177	    errno_cmp = ecmp;
178	    return *this;
179	  }
180	
181	  void explainError() override {
182	    if (!return_cmp.compare(actual_return)) {
183	      if constexpr (cpp::is_floating_point_v<T>) {
184	        tlog << "Expected return value to be " << return_cmp.str() << ": "
185	             << str(fputil::FPBits<T>(return_cmp.expected)) << '\n'
186	             << "                    But got: "
187	             << str(fputil::FPBits<T>(actual_return)) << '\n';
188	      } else {
189	        tlog << "Expected return value to be " << return_cmp.str() << " "
190	             << return_cmp.expected << " but got " << actual_return << ".\n";
191	      }
192	    }
193	
194	    if constexpr (!ignore_errno()) {
195	      if (!errno_cmp.compare(actual_errno)) {
196	        auto actual_str = try_get_errno_name(actual_errno);
197	        tlog << "Expected errno to be ";
198	        errno_cmp.print_expected();
199	        tlog << " but got " << (actual_str ? *actual_str : "<unknown>") << "("
200	             << actual_errno << ").\n";
201	      }
202	    }
203	  }
204	
205	  bool match(T got) {
206	    actual_return = got;
207	    actual_errno = libc_errno;
208	    libc_errno = 0;
209	    if constexpr (ignore_errno())
210	      return return_cmp.compare(actual_return);
211	    else
212	      return return_cmp.compare(actual_return) &&
213	             errno_cmp.compare(actual_errno);
214	  }
215	};
216	
217	} // namespace internal
218	
219	namespace ErrnoSetterMatcher {
220	
221	template <typename T> internal::Comparator<T> LT(T val) {
222	  return internal::Comparator<T>{internal::CompareAction::LT, val};
223	}
224	
225	template <typename T> internal::Comparator<T> LE(T val) {
226	  return internal::Comparator<T>{internal::CompareAction::LE, val};
227	}
228	
229	template <typename T> internal::Comparator<T> GT(T val) {
230	  return internal::Comparator<T>{internal::CompareAction::GT, val};
231	}
232	
233	template <typename T> internal::Comparator<T> GE(T val) {
234	  return internal::Comparator<T>{internal::CompareAction::GE, val};
235	}
236	
237	template <typename T> internal::Comparator<T> EQ(T val) {
238	  return internal::Comparator<T>{internal::CompareAction::EQ, val};
239	}
240	
241	template <typename T> internal::Comparator<T> NE(T val) {
242	  return internal::Comparator<T>{internal::CompareAction::NE, val};
243	}
244	
245	template <typename RetT = int>
246	internal::ErrnoSetterMatcher<RetT> Succeeds(RetT ExpectedReturn = 0,
247	                                            int ExpectedErrno = 0) {
248	  return internal::ErrnoSetterMatcher<RetT>(EQ(ExpectedReturn),
249	                                            EQ(ExpectedErrno));
250	}
251	
252	template <typename RetT = int>
253	internal::ErrnoSetterMatcher<RetT> Fails(int ExpectedErrno,
254	                                         RetT ExpectedReturn = -1) {
255	  return internal::ErrnoSetterMatcher<RetT>(EQ(ExpectedReturn),
256	                                            EQ(ExpectedErrno));
257	}
258	
259	template <typename RetT = int>
260	internal::ErrnoSetterMatcher<RetT> Fails(const ErrnoList &ExpectedErrs,
261	                                         RetT ExpectedReturn = -1) {
262	  return internal::ErrnoSetterMatcher<RetT>(EQ(ExpectedReturn), ExpectedErrs);
263	}
264	
265	template <typename... Args> inline ErrnoList any_of(Args... args) {
266	  return ErrnoList{{static_cast<int>(args)...}, sizeof...(args)};
267	}
268	
269	template <typename RetT = int> class ErrnoSetterMatcherBuilder {
270	public:
271	  template <typename T> using Cmp = internal::Comparator<T>;
272	  ErrnoSetterMatcherBuilder(Cmp<RetT> cmp) : return_cmp(cmp) {}
273	
274	  internal::ErrnoSetterMatcher<RetT> with_errno(internal::ErrnoCheck cmp) {
275	    return internal::ErrnoSetterMatcher<RetT>(return_cmp, cmp);
276	  }
277	
278	private:
279	  Cmp<RetT> return_cmp;
280	};
281	
282	template <typename RetT>
283	ErrnoSetterMatcherBuilder<RetT> returns(internal::Comparator<RetT> cmp) {
284	  return ErrnoSetterMatcherBuilder<RetT>(cmp);
285	}
286	
287	} // namespace ErrnoSetterMatcher
288	
289	} // namespace testing
290	} // namespace LIBC_NAMESPACE_DECL
291	
292	#endif // LLVM_LIBC_TEST_ERRNOSETTERMATCHER_H
293

